//! Static help and canonical native registry listing; no workspace/model load.
use super::{bounded,capture_command,MAX_STDERR,OUTER_WATCHDOG};use std::{io::{self,Write},path::PathBuf,process::{Command,ExitCode}};
fn backend(args:&[String])->io::Result<PathBuf>{let mut program=None;let mut at=1;while let Some(arg)=args.get(at){at+=1;if arg=="--native-dmbc"{let p=PathBuf::from(args.get(at).ok_or_else(||io::Error::new(io::ErrorKind::InvalidInput,"native executable missing"))?);at+=1;if !p.is_absolute()||program.replace(p).is_some(){return Err(io::Error::new(io::ErrorKind::InvalidInput,"list needs one absolute native executable"))}}}program.ok_or_else(||io::Error::new(io::ErrorKind::InvalidInput,"native list needs --native-dmbc ABSOLUTE_EXE"))}
fn run(args:&[String],out:&mut impl Write,err:&mut impl Write)->io::Result<u8>{match args.first().map(String::as_str){None|Some("help"|"--help"|"-h")=>{writeln!(out,"{}",crate::cli_usage::HELP)?;Ok(0)},Some("list")=>{let mut command=Command::new(backend(args)?);command.arg("analyze-list");let(status,output,diagnostics)=capture_command(command,OUTER_WATCHDOG,|r|bounded(r,64*1024),|r|bounded(r,MAX_STDERR))?;err.write_all(&diagnostics)?;if status.code()!=Some(0){return Ok(if status.code()==Some(75){75}else{2})}out.write_all(&output)?;Ok(0)},_=>Err(io::Error::new(io::ErrorKind::InvalidInput,"not a native metadata command"))}}
pub(super)fn cli(args:&[String])->Option<ExitCode>{if !matches!(args.first().map(String::as_str),None|Some("help"|"--help"|"-h"|"list")){return None}Some(match run(args,&mut io::stdout().lock(),&mut io::stderr().lock()){Ok(code)=>ExitCode::from(code),Err(error)=>{eprintln!("analyze: {error}");ExitCode::from(2)}})}
#[cfg(test)]mod controls{use super::*;
 #[test]fn original_help_needs_no_cwd_root_backend_or_workspace_and_preserves_actual_bytes(){for cmd in ["help","--help","-h"]{let mut out=Vec::new();let mut err=Vec::new();assert_eq!(run(&[cmd.into(),"--root".into(),"not-a-workspace".into()],&mut out,&mut err).unwrap(),0);assert_eq!(out,[crate::cli_usage::HELP.as_bytes(),b"\n"].concat());assert!(err.is_empty())}}
 #[test]fn help_keeps_actual_first_output_io(){struct Stop;impl Write for Stop{fn write(&mut self,_:&[u8])->io::Result<usize>{Err(io::Error::from_raw_os_error(1450))}fn flush(&mut self)->io::Result<()>{Ok(())}}assert_eq!(run(&[],&mut Stop,&mut Vec::new()).unwrap_err().raw_os_error(),Some(1450));}
 #[test]fn list_metadata_preserves_original_ignored_arguments_but_requires_one_explicit_absolute_backend(){let absolute=if cfg!(windows){"E:/actual/dmbc.exe"}else{"/actual/dmbc"};let args=["list","--root","missing","--lint","ignored","--native-dmbc",absolute,"--unknown-original-list-flag"].map(str::to_owned);assert_eq!(backend(&args).unwrap(),PathBuf::from(absolute));assert!(backend(&["list".into()]).is_err());assert!(backend(&["list".into(),"--native-dmbc".into(),"relative".into()]).is_err());}
}
